  "recovered_c": "uint64_t fn_20(uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < len) {\n    return 0xFFFFFFFFFFFFFFFF;\n  }\n  uint8_t p[8];\n  for (size_t n = 0; n < 8; n++) {\n    p[n] = (uint8_t)n;\n  }\n  uint64_t sd = arg;\n  for (size_t n = 7; n != 0; n--) {\n    size_t uVar3 = sd % (n + 1);\n    sd = sd / (n + 1);\n    uint8_t uVar1 = p[n];\n    p[n] = p[uVar3];\n    p[uVar3] = uVar1;\n  }\n  for (size_t b = 0; b + 8 <= len; b += 8) {\n    for (size_t n = 0; n < 8; n++) {\n      out[b + n] = in[p[n] + b];\n    }\n  }\n  for (; b < len; b++) {\n    out[b] = in[b];\n  }\n  return len;\n}"
